#include <stdio.h>

/* Returns 1 if n is prime, otherwise 0 */
int isPrime(int n) {
    int i;
    if (n < 2)
        return 0;
    for (i = 2; i <= n / i; i++) {   /* same as i * i <= n, without overflow */
        if (n % i == 0)
            return 0;
    }
    return 1;
}

int main(void) {
    int n;
    printf("Enter a positive integer: ");
    if (scanf("%d", &n) != 1) {
        printf("Invalid input\n");
        return 1;
    }
    if (isPrime(n))
        printf("%d is a prime number\n", n);
    else
        printf("%d is not a prime number\n", n);
    return 0;
}

