#include <stdio.h>
#include <string.h>

/* Reverse a string in place using two pointers */
void reverse(char *s) {
    size_t len = strlen(s);
    char *left, *right, t;
    if (len < 2)
        return;
    left = s;
    right = s + len - 1;
    while (left < right) {
        t = *left;
        *left = *right;
        *right = t;
        left++;
        right--;
    }
}

int main(void) {
    char str[100], copy[100];
    printf("Enter a word: ");
    if (scanf("%99s", str) != 1)
        return 1;
    strcpy(copy, str);
    reverse(copy);
    printf("Reversed: %s\n", copy);
    if (strcmp(str, copy) == 0)
        printf("%s is a palindrome\n", str);
    else
        printf("%s is not a palindrome\n", str);
    return 0;
}

