    int roll;
    char name[50];
    float marks;
};

int main(void) {
    struct student s[50], t, best;
    int n, i, found = 0;
    FILE *fp;

    printf("Number of students (1-50): ");
    if (scanf("%d", &n) != 1 || n < 1 || n > 50) {
        printf("Invalid number\n");
        return 1;
    }
    for (i = 0; i < n; i++) {
        printf("Roll, name and marks of student %d: ", i + 1);
