            printf("Invalid input\n");
            return 1;
        }
    }

    /* Write all records to the file */
    fp = fopen("students.txt", "w");
    if (fp == NULL) {
        perror("students.txt");
        return 1;
    }
    for (i = 0; i < n; i++)
        fprintf(fp, "%d %s %.2f\n", s[i].roll, s[i].name, s[i].marks);
    fclose(fp);

    /* Read the records back and find the highest marks */
    fp = fopen("students.txt", "r");
    if (fp == NULL) {
        perror("students.txt");
        return 1;
    }
    while (fscanf(fp, "%d %49s %f", &t.roll, t.name, &t.marks) == 3) {
        if (!found || t.marks > best.marks) {
            best = t;
            found = 1;
        }
    }
    fclose(fp);

    if (found)
        printf("Highest marks: %s (roll %d) with %.2f\n", best.name, best.roll, best.marks);
    return 0;
}

