A struct Student holds one record; an array of structs holds the whole file.

#include <stdio.h>
#define MAX 100

struct Student {
    int id;
    char name[50];
    char dept[20];
    float cgpa;
};

int main(void) {
    struct Student s[MAX];
    FILE *in, *out;
    int n = 0, i, selected = 0;
    float sum = 0.0f;

    /* a) Read all records from students.txt */
    in = fopen("students.txt", "r");
    if (in == NULL) {
        printf("Cannot open students.txt\n");
        return 1;
    }
    while (n < MAX &&
           fscanf(in, "%d,%49[^,],%19[^,],%f",
                  &s[n].id, s[n].name, s[n].dept, &s[n].cgpa) == 4)
        n++;
    fclose(in);

    /* b) Display all records */
    printf("%-5s %-10s %-5s %s\n", "ID", "Name", "Dept", "CGPA");
    for (i = 0; i < n; i++)
        printf("%-5d %-10s %-5s %.2f\n", s[i].id, s[i].name, s[i].dept, s[i].cgpa);

    /* c) + d) CGPA > 3.50: show and write to new.txt */
    out = fopen("new.txt", "w");
    if (out == NULL) {
        printf("Cannot create new.txt\n");
        return 1;
    }
    printf("\nStudents with CGPA > 3.50:\n");
    for (i = 0; i < n; i++) {
        if (s[i].cgpa > 3.50f) {
            printf("%-5d %-10s %-5s %.2f\n", s[i].id, s[i].name, s[i].dept, s[i].cgpa);
            fprintf(out, "%d,%s,%s,%.2f\n", s[i].id, s[i].name, s[i].dept, s[i].cgpa);
            selected++;
        }
    }
    fclose(out);
    printf("%d record(s) written to new.txt\n", selected);

    /* e) Average CGPA */
    for (i = 0; i < n; i++)
        sum += s[i].cgpa;
    if (n > 0)
        printf("\nAverage CGPA = %.2f\n", sum / n);

    /* f) Total number of students */
    printf("Total Students = %d\n", n);
    return 0;
}

