struct Student {            /* different types under one name */
    int roll;
    char name[20];
    float cgpa;
};

int main(void) {
    int marks[3] = {78, 85, 92};                  /* same type, by index */
    struct Student s = {101, "Rahim", 3.75f};     /* mixed types, by name */

    printf("%d %d\n", marks[0], marks[2]);
    printf("%d %s %.2f\n", s.roll, s.name, s.cgpa);
    return 0;
