Idea: find the length by walking to '\0', then swap s[i] and s[j] from both ends until they meet. This reverses in place with O(n) time and O(1) extra space.

#include <stdio.h>

/* Length without strlen(): walk to the '\0' */
int length(const char *s) {
    int n = 0;
    while (s[n] != '\0')
        n++;
    return n;
}

/* Reverse in place with two indices moving towards each other */
void reverse(char *s) {
    int i = 0, j = length(s) - 1;
    char t;
    while (i < j) {
        t = s[i];
        s[i] = s[j];
        s[j] = t;
        i++;
        j--;
    }
}

int main(void) {
    char s[100];
    int n;

    printf("Enter a string: ");
    if (fgets(s, sizeof s, stdin) == NULL)
        return 1;
    n = length(s);
    if (n > 0 && s[n - 1] == '\n')      /* drop the newline kept by fgets */
        s[n - 1] = '\0';

    reverse(s);
    printf("Reversed: %s\n", s);
    return 0;
}

