/* true if s[lo..hi] reads the same both ways */
bool isPal(const char *s, int lo, int hi) {
    if (lo >= hi)
        return true;            /* 0 or 1 character left */
    if (s[lo] != s[hi])
        return false;
    return isPal(s, lo + 1, hi - 1);
}

