struct Node {
    int data;
    struct Node *next;      /* points to a structure of the same type */
};

int main(void) {
    struct Node *head = NULL, *p;
    int i;

    for (i = 3; i >= 1; i--) {          /* insert 3, 2, 1 at the front */
        p = (struct Node *) malloc(sizeof(struct Node));
        if (p == NULL)
            return 1;
        p->data = i * 10;
        p->next = head;
        head = p;
    }
    for (p = head; p != NULL; p = p->next)
        printf("%d -> ", p->data);
    printf("NULL\n");

    while (head != NULL) {              /* free the list */
        p = head->next;
        free(head);
        head = p;
    }
    return 0;
}

