model_answer_en:
The number of records is read at run time, so the array of structures is allocated with malloc.

#include <stdio.h>
#include <stdlib.h>

struct Employee {
    int id;
    char name[30];
    float salary;
};

int main(void) {
    struct Employee *e;
    int n, i;

    printf("How many employees? ");
    if (scanf("%d", &n) != 1 || n <= 0) {
        printf("Invalid number\n");
        return 1;
    }
    e = (struct Employee *) malloc(n * sizeof(struct Employee));
    if (e == NULL) {
        printf("Memory allocation failed\n");
        return 1;
    }
    for (i = 0; i < n; i++) {
        printf("Enter id, name and salary of employee %d: ", i + 1);
        scanf("%d %29s %f", &e[i].id, e[i].name, &e[i].salary);
    }
    printf("\n%-5s %-10s %10s\n", "ID", "Name", "Salary");
    for (i = 0; i < n; i++)
        printf("%-5d %-10s %10.2f\n", (e + i)->id, (e + i)->name, (e + i)->salary);
    free(e);
    return 0;
}

Sample run (input 3, then 101 Rahim 35000, 102 Karim 42000.5, 103 Nila 28000):
ID    Name           Salary
101   Rahim        35000.00
102   Karim        42000.50
103   Nila         28000.00

Points: malloc(n * sizeof(struct Employee)) reserves exactly n records; always check for NULL; e[i].id and (e + i)->id are the same member; %29s stops a long name from overflowing name[30]; free(e) returns the memory. calloc(n, sizeof(struct Employee)) would also zero the block, and realloc can enlarge it when more employees join.

