#include <stdio.h>

struct Account {
    char accNo[12];
    char name[30];
    double balance;
};

int main(void) {
    struct Account a[5] = {
        {"SB-1001", "Rahim", 52000.50},
        {"SB-1002", "Karim", 125000.00},
        {"SB-1003", "Nila", 8750.25},
        {"SB-1004", "Ayesha", 99999.99},
        {"SB-1005", "Rafi", 125000.00}
    };
    int n = 5, i, j;
    struct Account t;
    double total = 0.0;

    for (i = 0; i < n; i++)
        total += a[i].balance;

    /* bubble sort by balance, highest first; whole structures are swapped */
    for (i = 0; i < n - 1; i++)
        for (j = 0; j < n - 1 - i; j++)
            if (a[j].balance < a[j + 1].balance) {
                t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
            }

    printf("%-8s %-8s %12s\n", "AccNo", "Name", "Balance");
    for (i = 0; i < n; i++)
        printf("%-8s %-8s %12.2f\n", a[i].accNo, a[i].name, a[i].balance);
    printf("Total deposit = %.2f\n", total);
    printf("Average balance = %.2f\n", total / n);
    return 0;
}

Output:
AccNo    Name          Balance
SB-1002  Karim       125000.00
SB-1005  Rafi        125000.00
SB-1004  Ayesha       99999.99
SB-1001  Rahim        52000.50
SB-1003  Nila          8750.25
Total deposit = 410750.74
Average balance = 82150.15

Points: a structure groups the three fields of one account; t = a[j] copies a whole structure (structures can be assigned, so the swap needs no member-by-member copy); the strict < keeps Karim before Rafi when balances are equal (bubble sort is stable); total = 410750.74 and average = 410750.74 / 5 = 82150.148, printed as 82150.15.

